import{_ as d,o as a,c as r,a0 as e}from"./chunks/framework.ZoVXsKRZ.js";const g=JSON.parse('{"title":"国标麻将「竞赛规则」入门","description":"","frontmatter":{"lastUpdated":true},"headers":[],"relativePath":"skills/guobiao.md","filePath":"skills/guobiao.md","lastUpdated":1784794489000}'),l={name:"skills/guobiao.md"};function o(n,t,h,i,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="国标麻将「竞赛规则」入门" tabindex="-1">国标麻将「竞赛规则」入门 <a class="header-anchor" href="#国标麻将「竞赛规则」入门" aria-label="Permalink to &quot;国标麻将「竞赛规则」入门&quot;">​</a></h1><p>国标麻将（中国麻将竞赛规则）是国家体育总局于 1998 年颁布的标准竞技规则，是所有麻将赛事（包括世界麻将锦标赛）的官方规则。它整合了各地麻将的精华，是目前最完整、最复杂的麻将体系。</p><h2 id="基本参数" tabindex="-1">基本参数 <a class="header-anchor" href="#基本参数" aria-label="Permalink to &quot;基本参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>人数</strong></td><td>4 人</td></tr><tr><td><strong>牌数</strong></td><td>144 张（含春、夏、秋、冬、梅、兰、竹、菊 8 张花牌）</td></tr><tr><td><strong>番数门槛</strong></td><td>必须达到 <strong>8 番</strong> 才能胡牌</td></tr><tr><td><strong>花牌</strong></td><td>摸到花牌立即补牌，花牌计 1 番/张</td></tr><tr><td><strong>结算</strong></td><td>按番数计算，番数越高赢得越多</td></tr></tbody></table><hr><h2 id="核心特色" tabindex="-1">核心特色 <a class="header-anchor" href="#核心特色" aria-label="Permalink to &quot;核心特色&quot;">​</a></h2><h3 id="_1-8-番起胡" tabindex="-1">1. 8 番起胡 <a class="header-anchor" href="#_1-8-番起胡" aria-label="Permalink to &quot;1. 8 番起胡&quot;">​</a></h3><p>国标最大的门槛：<strong>必须有 8 番以上的番型组合才能胡牌。</strong> 这意味着不能&quot;鸡胡&quot;，必须有意识地做牌。</p><p>新手最常用的 8 番组合策略：</p><table tabindex="0"><thead><tr><th>组合</th><th style="text-align:center;">番数</th><th>说明</th></tr></thead><tbody><tr><td>花牌 x2 + 门前清 + 平和 + 断幺</td><td style="text-align:center;">2+2+2+2=8</td><td>最基础的组合</td></tr><tr><td>混一色 + 门前清 + 幺九刻</td><td style="text-align:center;">6+2+1=9</td><td>做混一色</td></tr><tr><td>碰碰胡 + 断幺</td><td style="text-align:center;">6+2=8</td><td>全碰不贪大</td></tr><tr><td>全带幺 + 门前清</td><td style="text-align:center;">4+2=6…</td><td>还差 2 番需要花牌凑</td></tr></tbody></table><h3 id="_2-花牌系统" tabindex="-1">2. 花牌系统 <a class="header-anchor" href="#_2-花牌系统" aria-label="Permalink to &quot;2. 花牌系统&quot;">​</a></h3><p>国标有 8 张花牌，每张计 1 番：</p><ul><li><strong>春、夏、秋、冬</strong> — 对应座位（庄=春, 南=夏, 西=秋, 北=冬）</li><li><strong>梅、兰、竹、菊</strong> — 4 张通用花</li></ul><p>摸到花牌 → 立即亮出放桌角 → 从牌尾补一张 → 花牌自动加番。</p><h3 id="_3-不重复计番原则" tabindex="-1">3. 不重复计番原则 <a class="header-anchor" href="#_3-不重复计番原则" aria-label="Permalink to &quot;3. 不重复计番原则&quot;">​</a></h3><p>国标有一个重要规则：<strong>同一副牌型中，互含关系的番型只计最高番。</strong></p><p>比如&quot;清一色&quot;（24 番）已经包含了&quot;无字&quot;（1 番），就不再单独算无字的 1 番。</p><hr><h2 id="番型分级速查" tabindex="-1">番型分级速查 <a class="header-anchor" href="#番型分级速查" aria-label="Permalink to &quot;番型分级速查&quot;">​</a></h2><h3 id="_88-番-最高级" tabindex="-1">88 番（最高级） <a class="header-anchor" href="#_88-番-最高级" aria-label="Permalink to &quot;88 番（最高级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>番型</th><th>说明</th></tr></thead><tbody><tr><td>大四喜</td><td>东南西北各一组刻子</td></tr><tr><td>大三元</td><td>中发白各一组刻子</td></tr><tr><td>九莲宝灯</td><td>1112345678999 + 同花色任意一张</td></tr><tr><td>四杠</td><td>四组杠子 + 一对将</td></tr><tr><td>连七对</td><td>同花色连续 7 对</td></tr><tr><td>十三幺</td><td>十三种幺九牌 + 任一对</td></tr></tbody></table><h3 id="_64-番" tabindex="-1">64 番 <a class="header-anchor" href="#_64-番" aria-label="Permalink to &quot;64 番&quot;">​</a></h3><table tabindex="0"><thead><tr><th>番型</th><th>说明</th></tr></thead><tbody><tr><td>小四喜</td><td>东南西北中三组刻子，另一组作将</td></tr><tr><td>小三元</td><td>中发白两组刻子，另一组作将</td></tr><tr><td>字一色</td><td>全部由字牌组成</td></tr><tr><td>清幺九</td><td>全部由 1 和 9 组成</td></tr></tbody></table><h3 id="_48-番" tabindex="-1">48 番 <a class="header-anchor" href="#_48-番" aria-label="Permalink to &quot;48 番&quot;">​</a></h3><table tabindex="0"><thead><tr><th>番型</th><th>说明</th></tr></thead><tbody><tr><td>一色四同顺</td><td>同花色四组相同的顺子</td></tr><tr><td>一色四节高</td><td>同花色四组递增的刻子</td></tr></tbody></table><h3 id="_24-32-番" tabindex="-1">24-32 番 <a class="header-anchor" href="#_24-32-番" aria-label="Permalink to &quot;24-32 番&quot;">​</a></h3><table tabindex="0"><thead><tr><th>番型</th><th>说明</th><th style="text-align:center;">番数</th></tr></thead><tbody><tr><td>清一色</td><td>同花色</td><td style="text-align:center;">24</td></tr><tr><td>一色三同顺</td><td>同花色三组相同顺子</td><td style="text-align:center;">24</td></tr><tr><td>全大</td><td>全部由 789 组成</td><td style="text-align:center;">24</td></tr><tr><td>全中</td><td>全部由 456 组成</td><td style="text-align:center;">24</td></tr><tr><td>全小</td><td>全部由 123 组成</td><td style="text-align:center;">24</td></tr><tr><td>三杠</td><td>三组杠子</td><td style="text-align:center;">32</td></tr><tr><td>混幺九</td><td>全部由幺九牌组成</td><td style="text-align:center;">32</td></tr></tbody></table><h3 id="常用低番-凑-8-番用" tabindex="-1">常用低番（凑 8 番用） <a class="header-anchor" href="#常用低番-凑-8-番用" aria-label="Permalink to &quot;常用低番（凑 8 番用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>番型</th><th>说明</th><th style="text-align:center;">番数</th></tr></thead><tbody><tr><td>门前清</td><td>不吃不碰不杠听牌</td><td style="text-align:center;">2</td></tr><tr><td>平和</td><td>全顺子 + 非字牌将</td><td style="text-align:center;">2</td></tr><tr><td>断幺</td><td>无 1、9 和字牌</td><td style="text-align:center;">2</td></tr><tr><td>一般高</td><td>两组相同的顺子</td><td style="text-align:center;">1</td></tr><tr><td>老少副</td><td>123 + 789 同花色</td><td style="text-align:center;">1</td></tr><tr><td>幺九刻</td><td>有 1/9/字牌的刻子</td><td style="text-align:center;">1</td></tr></tbody></table><hr><h2 id="新手策略" tabindex="-1">新手策略 <a class="header-anchor" href="#新手策略" aria-label="Permalink to &quot;新手策略&quot;">​</a></h2><h3 id="凑-8-番三步法" tabindex="-1">凑 8 番三步法 <a class="header-anchor" href="#凑-8-番三步法" aria-label="Permalink to &quot;凑 8 番三步法&quot;">​</a></h3><ol><li><strong>保底 2+2+2</strong>：门前清(2) + 平和(2) + 断幺(2) = 6 番，再摸 2 张花牌 = 8 番</li><li><strong>混一色路线</strong>：混一色(6) + 幺九刻(1) + 门前清(2) = 9 番</li><li><strong>碰碰胡路线</strong>：碰碰胡(6) + 断幺(2) = 8 番</li></ol><h3 id="关键提醒" tabindex="-1">关键提醒 <a class="header-anchor" href="#关键提醒" aria-label="Permalink to &quot;关键提醒&quot;">​</a></h3><ul><li><strong>花牌是宝贝</strong> — 每张花牌就是 1 番，凑门槛的神器</li><li><strong>不要轻易吃碰</strong> — 门前清值 2 番，冲 8 番很好用</li><li><strong>记番是基本功</strong> — 建议把上面的番型表存手机里，边打边查</li></ul><hr><h2 id="赛事信息" tabindex="-1">赛事信息 <a class="header-anchor" href="#赛事信息" aria-label="Permalink to &quot;赛事信息&quot;">​</a></h2><p>国标麻将每年都有正式赛事：</p><ul><li><strong>世界麻将锦标赛</strong>（WMC）</li><li><strong>中国麻将公开赛</strong></li><li><strong>各地麻协组织的积分赛</strong></li></ul><p>有兴趣参加比赛的，可以搜索当地麻将协会了解详情。</p><hr><p><em>国标规则细节繁多，赛事级别有正式裁判执裁。娱乐局可适当放宽。</em></p>',42)])])}const u=d(l,[["render",o]]);export{g as __pageData,u as default};
